    # Read n
    try:
        line = steamer.readline()
        if not line:
            return ""
        n = int(line.strip())
    except:
        return ""

    # Query 1: [1, n] - get all characters
    try:
        steamer.send("? 1 {}".format(n))
        substrings1 = steamer.readline().strip().split('\n')
        # Count character frequencies in all substrings
        counts1 = {}
        for sub in substrings1:
            for c in sub:
                counts1[c] = counts1.get(c, 0) + 1
    except Exception as e:
        steamer.close()
        return ""

    # Query 2: [1, n-1] if n > 1 to help identify characters
    if n > 1:
        try:
            steamer.send("? 1 {}".format(n - 1))
            substrings2 = steamer.readline().strip().split('\n')
            counts2 = {}
            for sub in substrings2:
                for c in sub:
                    counts2[c] = counts2.get(c, 0) + 1
        except Exception as e:
            steamer.close()
            return ""
    else:
        # For n=1, we need to query [2,1] which is invalid, so skip
        pass

    # Query 3: Try to identify remaining characters
    # For strings with mixed characters, we often need more info
    if n > 2:
        try:
            steamer.send("? 2 {}".format(n))
            substrings3 = steamer.readline().strip().split('\n')
            counts3 = {}
            for sub in substrings3:
                for c in sub:
                    counts3[c] = counts3.get(c, 0) + 1
        except Exception as e:
            steamer.close()
            return ""
    else:
        # For n=2, we need additional query to distinguish characters
        # Query [2,2] to get s[2]
        if n == 2:
            try:
                steamer.send("? 2 2")
                substrings3 = steamer.readline().strip().split('\n')
                # s[2] is just the single characters
                chars2 = set()
                for sub in substrings3:
                    for c in sub:
                        chars2.add(c)
            except Exception as e:
                steamer.close()
                return ""
        else:
            steamer.go_end()
            # if n > 2, we stop and try to reconstruct from first query
            steamer.close()
            return ""

    left = steamer.go_end()
    steamer.close()

    # Based on the pattern from solution test cases, the approach is simpler:
    # We use first query to get the main structure
    # Then use second/third queries to disambiguate

    if n <= 1:
