    # answers[j] = timestep or -1 if never reachable
    answers = [-1] * (m + 1)

    # Set of achievable values at current step
    achievable = {0}

    for step in range(1, n + 1):
        parts = lines[step].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])

        x = x_prime / 100000.0
        new_achievable = set()

        for k in achievable:
            # Can apply operation 0 to y times
            curr_k = k

            # Try each possible number of applications
            for a in range(y + 1):
                if a == 0:
                    new_achievable.add(k)
                else:
                    # Apply the operation a times
                    for _ in range(a):
                        if t == 1:
                            # ceil(k + x)
                            curr_k = math.ceil(curr_k + x)
                        else:
                            # ceil(k * x)
                            curr_k = math.ceil(curr_k * x)

                    new_achievable.add(curr_k)

        # Update achievable set and track first_reached values
        achievable = new_achievable

        # Mark newly reachable values for this step
        for val in list(achievable):
            if 1 <= val <= m and answers[val] == -1:
                answers[val] = step

    # Convert to string output (answers[1] to answers[m])
    return ' '.join(str(answers[j]) for j in range(1, m + 1))

