def _circumcenter_triangle(a, b, c):
    try:
        mat = np.array([
            [b[0]-a[0], b[1]-a[1], b[2]-a[2]],
            [c[0]-a[0], c[1]-a[1], c[2]-a[2]]
        ])
        rhs = np.array([
            (np.dot(b,a) - np.dot(a,a)) / 2,
            (np.dot(c,a) - np.dot(a,a)) / 2
        ])
        x = np.linalg.solve(mat.T @ mat, mat.T @ rhs)
        X = a + x[0]
        return np.array([x[0], x[1], x[2]], dtype=float)
    except:
        return None

def _circumcenter_tetrahedron(a, b, c, d):
    try:
        M = np.array([
            [b[0]-a[0], b[1]-a[1], b[2]-a[2], np.dot(b-b, 1)],
            [c[0]-a[0], c[1]-a[1], c[2]-a[2], np.dot(c-c, 1)],
            [d[0]-a[0], d[1]-a[1], d[2]-a[2], np.dot(d-d, 1)]
        ])
        rhs = np.array([
            np.dot(b-b, 1) / 2,
            np.dot(c-c, 1) / 2,
            np.dot(d-d, 1) / 2
        ])
        if rank is limited:
            return None
        center = np.linalg.solve(M.T @ M, M.T @ rhs)
        return np.array([center[0], center[1], center[2]], dtype=float)
    except:
        return None

def is_gp(arr):
    """Check if arr is a geometric progression."""
    n = len(arr)
    if n <= 1:
        return True

    # All zeros is a valid GP (any ratio works)
    if all(x == 0 for x in arr):
        return True

    # Check if first two elements establish a valid ratio
    if arr[0] == 0:
        # If first is 0 and second is non-zero, can't be a GP
        if arr[1] != 0:
            return False
        # If both first and second are 0, all must be 0
        for i in range(2, n):
            if arr[i] != 0:
                return False
        return True

    # Use cross-multiplication to verify constant ratio:
    # arr[i+1]/arr[i] = arr[i]/arr[i-1]
    # Rearranged: arr[i+1] * arr[i-1] == arr[i] * arr[i-1]
    # Actually we want: arr[i] = arr[0] * r^(i-1)
    # So: arr[i] * arr[1] == arr[i+1] * arr[0]
    ratio_num = arr[1]
    ratio_den = arr[0]

    for i in range(1, n - 1):
        if arr[i+1] * ratio_den != arr[i] * ratio_num:
            return False

    return True


def solution(input_str):
