    arr = list(map(int, lines[1].split()))

    # Check if already a GP
    if is_gp(arr):
        return "0\n"

    # Try removing each element
    for i in range(n):
        test = arr[:i] + arr[i+1:]
        if is_gp(test):
            return "1\n"

    return "2\n"


