    right_valid = []
    for mask in range(1 << n_right):
        valid = True
        for i in range(n_right):
            idx = n_left + i
            if (mask >> i) & 1:
                # Check if any neighbor in right mask exists
                if (adj[idx] & (mask << n_left)) == 0 or (adj[idx] & (mask << n_left)) == (1 << (i + n_left)):
