    if not lines:
        return ''
    t = int(lines[0])
    idx = 1
    results = []

    for _ in range(t):
        if idx >= len(lines):
            break
        n, m = map(int, lines[idx].split())
        idx += 1
        grid = []
        for i in range(n):
            row_str = lines[idx + i]
            row = [int(c) for c in row_str[0:m] if c in '01']
            grid.append(row)
        idx += n

        count = count_squares(grid, n, m)
        results.append(str(count))

    return '\n'.join(results)

def count_squares(grid, n, m):
    total = 0
    # Axis-aligned squares
    total += count_axis_aligned(grid, n, m)
    # Diagonal squares
    total += count_diagonal(grid, n, m)
    return total

def count_axis_aligned(grid, n, m):
    count = 0
    for r in range(n):
        for c in range(m):
            for k in range(2, min(n - r, m - c) + 1):
                # Check top border (row r, cols c to c+k-1)
                valid = True
                for j in range(k):
                    if grid[r][c + j] != 1:
                        valid = False
                        break
                if not valid:
                    continue

                # Check bottom border (row r+k-1, cols c to c+k-1)
                valid = all(grid[r + k - 1][c + j] == 1 for j in range(k))
                if not valid:
                    continue

                # Check left border (col c, rows r to r+k-1)
                valid = all(grid[r + i][c] == 1 for i in range(k))
                if not valid:
                    continue

                # Check right border (col c+k-1, rows r to r+k-1)
                valid = all(grid[r + i][c + k - 1] == 1 for i in range(k))
                if not valid:
                    continue

                # Check interior (rows r+1 to r+k-2, cols c+1 to c+k-2)
                valid = True
                for i in range(1, k - 1):
                    for j in range(1, k - 1):
                        if grid[r + i][c + j] != 0:
                            valid = False
                            break
                    if not valid:
                        break

                if valid:
                    count += 1
    return count

def count_diagonal(grid, n, m):
    count = 0
    for r in range(n):
        for c in range(m):
            for k in range(2, min(n - r, r, m - c, c) + 1):
                # Border: all cells with Manhattan distance k from center (r,c)
                border_ok = True
                for dr in range(-k, k + 1):
                    for dc in range(-k, k + 1):
                        if abs(dr) + abs(dc) == k:
                            nr, nc = r + dr, c + dc
                            if not (0 <= nr < n and 0 <= nc < m):
                                border_ok = False
                                break
                            if grid[nr][nc] != 1:
                                border_ok = False
                                break
                    if not border_ok:
                        break
                if not border_ok:
                    continue

                # Interior: all cells with Manhattan distance < k from center
                interior_ok = True
                for dr in range(-k + 1, k):
                    for dc in range(-k + 1, k):
                        if abs(dr) + abs(dc) < k:
                            nr, nc = r + dr, c + dc
                            if not (0 <= nr < n and 0 <= nc < m):
                                interior_ok = False
                                break
                            if grid[nr][nc] != 0:
                                interior_ok = False
                                break
                    if not interior_ok:
                        break

                if interior_ok:
                    count += 1
    return count

