        """Can row r from column c1 to c2 form a palindrome?"""
        row_segment = ''.join(matrix[r][j] for j in range(c1, c2 + 1))
        return check(row_segment)

    def is_col_palindrome(c, r1, r2):
        """Can column c from row r1 to r2 form a palindrome?"""
        col_segment = ''.join(matrix[i][c] for i in range(r1, r2 + 1))
