def solve_small(n, m):
    if n + m <= 3:
        return 0
    if n == 1:
        return (m // 3) * 2 if m % 3 == 0 or m % 3 == 1 else (m // 3 + 1) * 2 if m % 3 == 2 else 0
    if m == 1:
        return (n // 3) * 2 if n % 3 == 0 or n % 3 == 1 else (n // 3 + 1) * 2 if n % 3 == 2 else 0
    min_dim = min(n, m)
    if min_dim == 2:
        if max_dim := max(n, m) > 3:
            return (max_dim - 4) * 2 if max_dim % 3 == 0 or max_dim % 3 == 1 else (max_dim - 3) * 2 if max_dim % 3 < 2 else 0
        return 0
    return solve_simple(n, m)

def solve_large(n, m):
