                    graph[fp].append(fn)
                    in_degree[fn] += 1
                    added.add((fp, fn))

        # Back sequence constraints
        cards_pos_back = [i for i in range(n_val) if cards[i][1] == x]
        cards_neg_back = [i for i in range(n_val) if cards[i][1] == -x]
        for bp in cards_pos_back:
            for bn in cards_neg_back:
                if bp != bn and (bp, bn) not in added:
                    graph[bp].append(bn)
                    in_degree[bn] += 1
                    added.add((bp, bn))

    # Topological sort
    pq = [i for i in range(n_val) if in_degree[i] == 0]
    heapq.heapify(pq)

    result = []
    while pq:
        node = heapq.heappop(pq)
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(pq, neighbor)

    if len(result) != n_val:
