    front_seq = [cards[i][0] for i in result]
    back_seq = [cards[i][1] for i in result]

    if not (is_valid_bracket(front_seq) and is_valid_bracket(back_seq)):
        return "NO"

    output = ["YES"]
    for i in result:
        output.append(f"{cards[i][0]} {cards[i][1]}")

    return "\n".join(output)

