def count_partitions(b, n):
    """
    Count the number of ways to represent b as sum(a_i * n^i) with a_i >= 0.
    Recurrence: f(b, n) = sum(f(j, n) for j in range(floor(b/n) + 1))
    """
    if b == 0:
        return 1

    @lru_cache(maxsize=10**6)
    def f(val):
        if val == 0:
            return 1
        limit = val // n
        total = 0
        for j in range(limit + 1):
            total += f(j)
        return total

    return f(b)

