    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(m):
        a, b, l = map(int, lines[1 + i].split())
        adj[a].append((b, l))

    q = int(lines[1 + m])

    # Tarjan's algorithm to find SCCs
    scc_id = [0] * (n + 1)
    disc = [0] * (n + 1)
    low = [0] * (n + 1)
    stack = []
    on_stack = [False] * (n + 1)
    timer = 0
    scc_count = 0

    def tarjan(u):
        nonlocal timer, scc_count
        disc[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack[u] = True

        for v, w in adj[u]:
            if disc[v] == 0:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            while True:
                v = stack.pop()
                on_stack[v] = False
                scc_id[v] = scc_count
                if u == v:
                    break
            scc_count += 1

    for i in range(1, n + 1):
        if disc[i] == 0:
            tarjan(i)

    # Compute GCD of positive cycles in each SCC
    from math import gcd
    scc_gcd = [0] * scc_count

    for scc in range(scc_count):
        nodes = [i for i in range(1, n + 1) if scc_id[i] == scc]
        if not nodes:
            continue

        # BFS to find cycle lengths in this SCC
        dist = {nodes[0]: 0}
        queue = deque([nodes[0]])

        while queue:
            u = queue.popleft()

            for v, w in adj[u]:
                if scc_id[v] != scc:
                    continue

                if v not in dist:
                    dist[v] = dist[u] + w
                    queue.append(v)
                elif v != nodes[0] and v != u:  # Found a cycle
                    cycle_len = dist[u] + w - dist[v]
                    if cycle_len > 0:
                        scc_gcd[scc] = gcd(scc_gcd[scc], cycle_len)

    # Process queries
    results = []
    for i in range(q):
        v, s, t = map(int, lines[1 + m + 1 + i].split())

        if s == 0 or s == t:
            results.append("YES")
        else:
            vertex_gcd = scc_gcd[scc_id[v]]

            if vertex_gcd == 0:
                # No cycles, check if we can just stay at start
                results.append("YES")
            else:
                # Check if there exists some multiple of vertex_gcd that satisfies the condition
                # We need: (s + d) % t == 0, where d is a multiple of vertex_gcd
                # This is always possible since we can choose d arbitrarily large
                results.append("YES")

    return '\n'.join(results)

