def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []

    for i in range(1, n + 1):
        a, b, c, d = map(int, lines[i].split())
        points.append((a, b, c, d, i))

    def can_connect(idx1, idx2):
        a1, b1, c1, d1, _ = points[idx1]
        a2, b2, c2, d2, _ = points[idx2]

        # Check all 16 movement combinations
        # Each point can have either x+1, y+1, or no change to either
        # But we need at least one actual movement
        for dx1 in [0, 1]:
            for dy1 in [0, 1]:
                # Skip if no movement on point 1
                if dx1 == 0 and dy1 == 0:
                    continue
                for dx2 in [0, 1]:
                    for dy2 in [0, 1]:
                        # Skip if no movement on point 2
                        if dx2 == 0 and dy2 == 0:
                            continue

                        # New coordinates using integer arithmetic
                        # x_new = (a + dx*b) / b, y_new = (c + dy*d) / d
                        x1_new_num = a1 + dx1 * b1
                        y1_new_num = c1 + dy1 * d1
                        x2_new_num = a2 + dx2 * b2
                        y2_new_num = c2 + dy2 * d2

                        # Check collinearity with origin: x1_new * y2_new == x2_new * y1_new
                        # Using cross multiplication to avoid floating point issues:
                        # (x1_new_num/b1) * (y2_new_num/d2) == (x2_new_num/b2) * (y1_new_num/d1)
                        # x1_new_num * y2_new_num * b2 * d1 == x2_new_num * y1_new_num * b1 * d2
                        if (x1_new_num * y2_new_num * b2 * d1) == (x2_new_num * y1_new_num * b1 * d2):
                            return True

        return False

    # Greedy matching
    used = [False] * n
    moves = []

    for i in range(n):
        if used[i]:
            continue
        for j in range(i + 1, n):
            if used[j]:
                continue
            if can_connect(i, j):
                moves.append((points[i][4], points[j][4]))
                used[i] = True
                used[j] = True
                break

    # Build output
    output_lines = [str(len(moves))]
    for a, b in moves:
        output_lines.append(f"{a} {b}")

    return "\n".join(output_lines)

