    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    a = list(map(int, lines[m + 1].split()))

    def check(x):
        """Check if current assignment x satisfies all constraints"""
        for i in range(1, n + 1):
            val = 0
            if x[i - 1] == 1:  # counter i's own button is pressed
                val += 1
            for neighbor in adj[i]:
                if x[neighbor - 1] == 1:  # neighbor's button is pressed
                    val += 1
            if val == a[i - 1]:
                return False
        return True

    def backtrack(idx):
        if idx == n:
            return check(x)

        # Try pressing button (idx + 1) = 0 first
        x[idx] = 0
        if backtrack(idx + 1):
            return True

        # Try pressing button (idx + 1) = 1
        x[idx] = 1
        if backtrack(idx + 1):
            return True

        return False

    if not backtrack(0):
        return "-1"
    else:
        res = [i + 1 for i in range(n) if x[i] == 1]
        out = str(len(res))
        if res:
            out += "\n" + " ".join(map(str, res))
        return out + "\n" if res else out

