def build_adjacency(lines, n):
    adj = [[] for _ in range(n + 1)]
    for i in range(2, 2 + n - 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)
    return adj

def get_parent(P, n, start_node):
    P[start_node] = 0
    queue = deque([start_node])
    visited = {start_node}

    while queue:
        v = queue.popleft()
        for u in adj[P][v]:
            if u != P[v] and u not in visited:
                P[u] = v
                visited.add(u)
                queue.append(u)

def dfs(P, parent, k, ans):
    ans[0] += k[parent]
    if parent == 0:
        return
    for child in adj[parent]:
        if child != P[parent]:
            dfs(P, child, k, ans)

