        visited[start] = True
        queue = deque([start])

        while queue:
            v = queue.popleft()
            for u in adj[v]:
                if not visited[u]:
                    visited[u] = True
                    parent[u] = v
                    queue.append(u)

    parent = {s: 0}
    bfs_build_tree(s)

    # Topological sort (BFS order reversed)
    order = []
    queue = deque([s])
    visited = [False] * (n + 1)
    visited[s] = True
    while queue:
        v = queue.popleft()
        order.append(v)
        for u in adj[v]:
            if u not in visited:
                visited[u] = True
                parent[u] = v
                queue.append(u)

