MOD = 10**9 + 7

def tokenize(s):
    pos = 0
    tokens = []
    while pos < len(s):
        if s[pos].isdigit():
            start = pos
            while pos < len(s) and s[pos].isdigit():
                pos += 1
            num = int(s[start:pos])
            tokens.append(('NUMBER', num))
        elif s[pos] == '-':
            tokens.append(('RANGE', 0))
            pos += 1
        elif s[pos] == '(':
            tokens.append(('LPAREN', 0))
            pos += 1
        elif s[pos] == ')':
            tokens.append(('RPAREN', 0))
            pos += 1
        elif s[pos] == '+':
            tokens.append(('PLUS', 0))
            pos += 1
        else:
            pos += 1
    return tokens

def count_len(n):
    return len(str(n))

def concat_vals(v1, l1, v2, l2):
    result = (v1 * pow(10, l2, MOD) + v2) % MOD
    return result, l1 + l2

def concat_range(l, r):
    results = []
    for num in range(l, r + 1):
        s = str(num)
        results.append((int(s) % MOD, len(s)))
    v2, l2 = results[0]
    for v1, l1 in results[1:]:
        v2, l2 = concat_vals(v2, l2, v1, l1)
    return v2, l2

def concat_group(l, r, start, end, n):
    v = 0
    lc = 0
    for i in range(start, end + 1):
        v, lc = concat_vals(v, lc, str(i)[n // 10], len(str(i)[n // 10]))
    return v, lc

