    def big_string_concat(s1, s2):
        # s1 = "..."
        # s2 = "..."
        l1 = len(s1)
        v1 = int(s1) % MOD
        v2 = int(s2) % MOD
        v1s = v1 * pow(10, len(s2), MOD) % MOD
        val = (v1s + v2) % MOD
        return val

    return str(result[0] % MOD)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        s = parts[0]
        c = int(parts[1])
        attempts.append((s, c))

    # Function to count matching positions between two strings
    def count_matches(s1, s2):
        return sum(a == b for a, b in zip(s1, s2))

    # Check if a code satisfies all constraints
    def satisfies(code):
        for (attempt_str, expected_count) in attempts:
            if count_matches(code, attempt_str) != expected_count:
                return False
        return True

    # Recursive backtracking to count valid codes
    def backtrack(pos, current_code):
        # Base case: if we've built the complete code
        if pos == n:
            return 1 if satisfies(current_code) else 0

        # Pruning: check if we've already violated some constraint
        partial_code = current_code[:pos]
        valid = True

        for (attempt_str, expected_count) in attempts:
            current_match = count_matches(partial_code, attempt_str)
            # If even filling remaining positions with same bits doesn't help
            remaining = n - pos
            if current_match > expected_count:
                valid = False
                break
            if current_match < expected_count - remaining:
                valid = False
                break

        if not valid:
            return 0

        # Try adding 0 or 1 at current position
        count = 0
        # Try 0
        count += backtrack(pos + 1, current_code + '0')
        # Try 1
        count += backtrack(pos + 1, current_code + '1')

        return count

    return str(backtrack(0, ""))
